type ExportableRecord = Record<string, unknown>;

const escapeCsvCell = (value: unknown): string => {
  const text = value == null ? '' : String(value);
  if (/[",\n\r]/.test(text)) {
    return `"${text.replace(/"/g, '""')}"`;
  }
  return text;
};

const downloadTextFile = (filename: string, content: string, mimeType: string) => {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
};

export const exportMsmeAuditCsv = (
  companyName: string,
  rows: Array<{ field: string; value: unknown }>,
): void => {
  const header = 'Field,Value';
  const body = rows
    .map((row) => `${escapeCsvCell(row.field)},${escapeCsvCell(row.value)}`)
    .join('\n');
  const safeName = companyName.replace(/[^\w.-]+/g, '_').slice(0, 48) || 'msme';
  const stamp = new Date().toISOString().slice(0, 10);
  downloadTextFile(
    `${safeName}_audit_${stamp}.csv`,
    `${header}\n${body}\n`,
    'text/csv;charset=utf-8',
  );
};

export const flattenForAuditExport = (
  label: string,
  data: ExportableRecord | null | undefined,
  prefix = '',
): Array<{ field: string; value: unknown }> => {
  if (!data) {
    return [];
  }

  return Object.entries(data).flatMap(([key, value]) => {
    const field = prefix ? `${prefix}.${key}` : key;
    if (value && typeof value === 'object' && !Array.isArray(value) && !(value instanceof Date)) {
      return flattenForAuditExport(label, value as ExportableRecord, field);
    }
    return [{ field: `${label}: ${field}`, value }];
  });
};
