import React from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  LinearProgress,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { Download } from '@mui/icons-material';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';

type EvidenceChecklistItem = {
  id: string;
  label: string;
  complete: boolean;
};

type ReportEndpoint = {
  key?: string;
  label?: string;
  endpoint?: string;
  available?: boolean;
  description?: string;
};

export type EvidenceWorkspaceData = {
  assessmentReady?: boolean;
  billCount?: number;
  transactionCount?: number;
  reportEndpoints?: ReportEndpoint[];
  scopes?: {
    scope1?: number;
    scope2?: number;
    scope3?: number;
    total?: number;
  };
  assuranceNote?: string;
  checklist?: EvidenceChecklistItem[];
};

type AuditorEvidenceWorkspaceProps = {
  companyName?: string;
  workspace?: EvidenceWorkspaceData | null;
  onExportCsv?: () => void;
};

const AuditorEvidenceWorkspace: React.FC<AuditorEvidenceWorkspaceProps> = ({
  companyName,
  workspace,
  onExportCsv,
}) => {
  const checklist = workspace?.checklist || [];
  const completed = checklist.filter((row) => row.complete).length;
  const percent = checklist.length
    ? Math.round((completed / checklist.length) * 100)
    : 0;
  const scopes = workspace?.scopes || {};
  const endpoints = (workspace?.reportEndpoints || []).filter((row) => row.available);

  return (
    <Stack spacing={2}>
      <Alert severity="info">
        {workspace?.assuranceNote
          || 'Credentialed reviewer workspace for evidence review. Platform does not issue assurance statements.'}
      </Alert>

      <Paper variant="outlined" sx={{ p: 2 }}>
        <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
          Evidence readiness — {companyName || 'MSME'}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          {completed} of {checklist.length || 0} evidence checks complete
        </Typography>
        <LinearProgress variant="determinate" value={percent} sx={{ height: 8, borderRadius: 1, mb: 2 }} />
        <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap">
          {checklist.map((item) => (
            <Chip
              key={item.id}
              size="small"
              color={item.complete ? 'success' : 'default'}
              label={item.label}
              variant={item.complete ? 'filled' : 'outlined'}
            />
          ))}
        </Stack>
      </Paper>

      <Paper variant="outlined" sx={{ p: 2 }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
          Inventory snapshot
        </Typography>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
          <Box>
            <Typography variant="caption" color="text.secondary">Total</Typography>
            <Typography variant="h6">{Number(scopes.total || 0).toFixed(1)} kg</Typography>
          </Box>
          <Box>
            <Typography variant="caption" color="text.secondary">Scope 1</Typography>
            <Typography variant="body1">{Number(scopes.scope1 || 0).toFixed(1)}</Typography>
          </Box>
          <Box>
            <Typography variant="caption" color="text.secondary">Scope 2</Typography>
            <Typography variant="body1">{Number(scopes.scope2 || 0).toFixed(1)}</Typography>
          </Box>
          <Box>
            <Typography variant="caption" color="text.secondary">Scope 3</Typography>
            <Typography variant="body1">{Number(scopes.scope3 || 0).toFixed(1)}</Typography>
          </Box>
          <Box>
            <Typography variant="caption" color="text.secondary">Bills</Typography>
            <Typography variant="body1">{workspace?.billCount ?? 0}</Typography>
          </Box>
          <Box>
            <Typography variant="caption" color="text.secondary">Transactions</Typography>
            <Typography variant="body1">{workspace?.transactionCount ?? 0}</Typography>
          </Box>
        </Stack>
        {onExportCsv ? (
          <Button
            startIcon={<Download />}
            size="small"
            variant="outlined"
            sx={{ mt: 2 }}
            onClick={onExportCsv}
          >
            Export audit CSV
          </Button>
        ) : null}
      </Paper>

      <Paper variant="outlined" sx={{ p: 2 }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
          Available reporting packs
        </Typography>
        {endpoints.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            No reporting endpoints marked available for this MSME yet.
          </Typography>
        ) : (
          <ScrollableTableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Pack</TableCell>
                  <TableCell>Endpoint</TableCell>
                  <TableCell>Notes</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {endpoints.map((row) => (
                  <TableRow key={row.key || row.label}>
                    <TableCell>{row.label || row.key}</TableCell>
                    <TableCell><code>{row.endpoint}</code></TableCell>
                    <TableCell>{row.description || '—'}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </ScrollableTableContainer>
        )}
      </Paper>
    </Stack>
  );
};

export default AuditorEvidenceWorkspace;
